CREATE INDEX idx_notes_deleted_at ON notes(deleted_at);

CREATE INDEX idx_notes_updated ON notes(updated_at DESC);

CREATE INDEX idx_notes_verse ON notes(verse_ref);

CREATE INDEX idx_pdf_hl_pdf ON pdf_highlights(pdf_id);

CREATE INDEX idx_playlist_items_playlist ON playlist_items(playlist_id, position);

CREATE UNIQUE INDEX idx_tag_edges_pair ON tag_edges(source_tag_id, target_tag_id);

CREATE INDEX idx_tag_edges_src ON tag_edges(source_tag_id);

CREATE INDEX idx_tag_edges_tgt ON tag_edges(target_tag_id);

CREATE INDEX idx_trail_conn_dest ON trail_connections(to_book_id, to_chapter);

CREATE INDEX idx_trail_conn_parent ON trail_connections(from_connection_id);

CREATE INDEX idx_trail_conn_session ON trail_connections(trail_session_id, created_at);

CREATE INDEX idx_trail_embeddings_ref ON trail_embeddings(ref_type, ref_id);

CREATE INDEX idx_trail_nodes_session ON trail_nodes(trail_session_id, order_index);

CREATE INDEX idx_trail_notes_anchor ON trail_notes(anchor_node_id);

CREATE INDEX idx_trail_notes_session ON trail_notes(trail_session_id);

CREATE INDEX idx_trail_paused_session ON trail_paused_intervals(trail_session_id);

CREATE UNIQUE INDEX idx_trail_tags_name ON trail_tags(name COLLATE NOCASE);

CREATE INDEX idx_ttm_session ON trail_tag_members(trail_session_id);

CREATE UNIQUE INDEX idx_verse_tags_name ON verse_tags(name COLLATE NOCASE);

CREATE INDEX idx_vtm_tag ON verse_tag_members(tag_id);

CREATE INDEX idx_vtv_loc ON verse_tag_verse(book_id, chapter);

CREATE INDEX idx_vtv_tag ON verse_tag_verse(tag_id);

CREATE INDEX idx_yt_handle   ON youtube_videos(channel_handle);

CREATE INDEX idx_yt_published ON youtube_videos(published DESC);

CREATE INDEX idx_yt_seg_video
          ON youtube_transcript_segments(video_id, start_ms);

CREATE INDEX idx_yt_transcripts_fetched
          ON youtube_transcripts(fetched_at DESC);

CREATE TRIGGER notes_ad
        AFTER DELETE ON notes BEGIN
          INSERT INTO notes_fts(notes_fts, rowid, title, content)
          VALUES ('delete', old.rowid, old.title, old.content);
        END;

CREATE TRIGGER notes_ai
        AFTER INSERT ON notes BEGIN
          INSERT INTO notes_fts(rowid, title, content)
          VALUES (new.rowid, new.title, new.content);
        END;

CREATE TRIGGER notes_au
        AFTER UPDATE ON notes BEGIN
          INSERT INTO notes_fts(notes_fts, rowid, title, content)
          VALUES ('delete', old.rowid, old.title, old.content);
          INSERT INTO notes_fts(rowid, title, content)
          VALUES (new.rowid, new.title, new.content);
        END;

CREATE TRIGGER yt_seg_ad
        AFTER DELETE ON youtube_transcript_segments BEGIN
          INSERT INTO youtube_transcripts_fts(youtube_transcripts_fts, rowid, text)
          VALUES ('delete', old.id, old.text);
        END;

CREATE TRIGGER yt_seg_ai
        AFTER INSERT ON youtube_transcript_segments BEGIN
          INSERT INTO youtube_transcripts_fts(rowid, text)
          VALUES (new.id, new.text);
        END;

CREATE TRIGGER yt_seg_au
        AFTER UPDATE ON youtube_transcript_segments BEGIN
          INSERT INTO youtube_transcripts_fts(youtube_transcripts_fts, rowid, text)
          VALUES ('delete', old.id, old.text);
          INSERT INTO youtube_transcripts_fts(rowid, text)
          VALUES (new.id, new.text);
        END;

